import pandas as pd

# Load datasets
sales_df = pd.read_csv("data/superstore.csv")
customer_df = pd.read_csv("data/customer_registry.csv")

print("========== EXECUTOR ==========")
print("Sales rows:", len(sales_df))
print("Customer registry rows:", len(customer_df))

# Example proof code generated by the AI
sales_records = sales_df.drop_duplicates().copy()

customer_records = customer_df.drop_duplicates().copy()

if customer_records["Customer ID"].duplicated().any():
    raise ValueError(
        "Customer registry has conflicting records for a Customer ID."
    )

sales_records = sales_records.loc[
    sales_records["Customer ID"].notna()
]

joined = sales_records.merge(
    customer_records,
    on="Customer ID",
    how="left",
    validate="many_to_one"
)

high_risk = (
    joined["Risk Level"]
    .astype("string")
    .str.strip()
    .str.casefold()
    .eq("high")
    .fillna(False)
)

eligible = joined.loc[
    high_risk & joined["Sales"].notna()
].copy()

negative_quantity_flag = (
    eligible["Quantity"].lt(0).fillna(False)
)

eligible = eligible.loc[
    ~negative_quantity_flag
].copy()

eligible["Currency Unit"] = (
    eligible["Currency Unit"]
    .astype("string")
    .str.strip()
    .str.upper()
)

exchange_rates = {
    "USD": 1.0,
    "EUR": 1.12
}

eligible["Exchange Rate"] = (
    eligible["Currency Unit"].map(exchange_rates)
)

if eligible["Exchange Rate"].isna().any():
    raise ValueError(
        "A high-risk transaction has a missing or unsupported currency unit."
    )

answer = (
    eligible["Sales"] *
    eligible["Exchange Rate"]
).sum()

print("\n========== RESULT ==========")
print("High-risk sales excluded:", answer)